-- 052. Олжас: тексты под озвучку (проверка voice-checker 25.11): «на дачу», «уже», «потом», «возит», числа словами.
-- Казахские слова (Мен, аке, Апа, Ойбай) пока без изменений. Только текст; audio_url сохраняется.
begin;
update characters set fixed_questions = jsonb_set(fixed_questions, '{1,a}', to_jsonb('"— На базаре. После — общага.\nВахтёрша скажет. Ребята скажут. Всё."'::json #>> '{}')) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R104' then jsonb_set(r, '{text}', to_jsonb('"Олжас слушает. На словах «высокий молодой парень» перестаёт дышать.\n— Высоких много. Мен не знаю.\n(пауза)\n— Аке туда с покупателями ездит. Он дом продаёт, он там всегда. Бабка старая, ей видится.\n(тихо, в пол)\n— Аке ни при чём. Ни при чём."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R108' then jsonb_set(r, '{text}', to_jsonb('"— Ну племянник. Апа моя ему сестра двоюродная. Это нельзя, что ли?\n(смотрит в пол)\n— Я тут живу. Каждый знает.\n— Аке мне помогает. Он родной. А что?"'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R191' then jsonb_set(r, '{text}', to_jsonb('"— Моё. Куртка, шапка, ботинки. — Смотрит в пол. — Деньги аке дал. Три тысячи. Я же сказал."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R192' then jsonb_set(r, '{text}', to_jsonb('"— Его пальцы. Он там был. Со мной и после меня. — Смотрит в пол. — Я всё сказал."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R213' then jsonb_set(r, '{text}', to_jsonb('"Олжас берёт шарф. Долго держит.\n— Он мёрз там. Я ему этот шарф под голову положил. — Пауза. — Я всё сказал. И про аке сказал."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R214' then jsonb_set(r, '{text}', to_jsonb('"— Деньги оттуда. Три тысячи аке отсчитал, в доме у немцев. — Смотрит в пол. — Я всё сказал."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R230' then jsonb_set(r, '{text}', to_jsonb('"— Ну да. С половины восьмого в общаге. — Смотрит в пол. — А он там один остался. Я же сказал."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R25' then jsonb_set(r, '{text}', to_jsonb('"Олжас на краешке стула, руки зажаты между колен.\nНа столе — протокол сравнения купюр и показания соседки Шмидтов.\nОн смотрит в пол. Долго. Потом — быстро, не останавливаясь:\n— Ойбай... Ладно. Я.\nЯ его взял. У ворот, в четверг. Темно было.\nМашину его к Шмидтам перегнал, под навес. Водить умею. Прав нет.\nВ подвале у немцев держал. Кормил. Чай носил. Не бил, клянусь.\nМатери его из автоматов звонил. А в субботу на остановке автомат сломан — я из того дома позвонил.\nПакет на остановке я забрал. Деньги оттуда, да.\n(поднимает голову) Но аке ни при чём! Слышите? Я сам придумал. Сам.\nУтром его отпустили... ну, отпустил кто-то. Машина там же стояла, под навесом. Сел, поехал к себе на Кок-Тобе. И угорел.\nБог наказал. Я его не трогал."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R41' then jsonb_set(r, '{text}', to_jsonb('"Кабинет. Перед Олжасом журнал вахтёрши и заключение Кана: царапины на кисти дяди. Задушен в субботу около десяти вечера.\n— Ну да. В общаге был. С половины восьмого.\n(смотрит на строчку, потом на бумагу Кана)\nЗначит... Я в общаге. А с ним аке остался. Один.\nМы ж вдвоём туда приехали. Никого больше не было.\nИ Игорь его ногтями... в десять вечера...\n(пауза)\nЯ ему в четверть седьмого передал, что Игорь сказал. «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу».\nОн тебя через мешок узнал, аке. По кашлю. И «Беломором» пахло, когда воду спускал.\nАке ничего не сказал. Деньги забрал, мне три тысячи отсчитал.\nБез четверти семь отправил: иди, утром за городом его отпущу.\nОйбай... Он же сказал — никто не пострадает."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R42' then jsonb_set(r, '{text}', to_jsonb('"Перед Олжасом серый шарф из подвала. Вы пересказываете, что видели Данияр на остановке и соседка у дома Шмидтов: высокий, молодой, спортивная куртка, ушанка. Печь топил.\nОлжас смотрит на шарф. Глаз не отводит.\n— Он мёрз там...\n(и сразу, быстро)\nЯ его взял. В четверг, у ворот. Темно было.\nМашину к Шмидтам перегнал. Водить умею, прав нет.\nВ подвале держал. Матери его из автоматов звонил. А в субботу — из того дома, там телефон.\nПакет на остановке я забрал.\nНо аке ни при чём! Я сам придумал, слышите? Сам.\nУтром его отпустили, машину отдали — там же стояла, под навесом. Он к себе на Кок-Тобе поехал. И угорел. Бог наказал. Не я.\nСосед по комнате перестаёт притворяться спящим. На запястьях Олжаса щёлкают наручники."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R82' then jsonb_set(r, '{text}', to_jsonb('"— Я же говорил. Держал его. Пальцы мои. А дальше меня там не было."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
commit;
